/* Editorial Utility direction — full documentation workspace: asymmetric rail on desktop, mobile drawer on small screens, specimen-sheet content with cobalt slash details. */
import { useEffect, useMemo, useState } from "react";
import { Copy, Search, ExternalLink } from "lucide-react";
import { LuminaIcon, type IconName } from "@/components/LuminaIcon";

type SectionKey = "overview" | "install" | "foundations" | "layout" | "components" | "samples" | "dashboard" | "admin" | "api" | "commerce" | "checkout" | "icons" | "theming" | "motion" | "accessibility";

type NavItem = { key: SectionKey; label: string; meta: string; icon: IconName };
const nav: NavItem[] = [
  { key: "overview", label: "Overview", meta: "Start here", icon: "spark" },
  { key: "install", label: "Installation", meta: "01", icon: "code" },
  { key: "foundations", label: "Foundations", meta: "02", icon: "palette" },
  { key: "layout", label: "Layout utilities", meta: "03", icon: "grid" },
  { key: "components", label: "Components", meta: "04", icon: "layers" },
  { key: "samples", label: "Samples & previews", meta: "05", icon: "activity" },
  { key: "dashboard", label: "Dashboard showcase", meta: "06", icon: "gauge" },
  { key: "admin", label: "Admin Kit", meta: "07", icon: "command" },
  { key: "api", label: "API reference", meta: "08", icon: "search" },
  { key: "commerce", label: "Commerce kit", meta: "09", icon: "bag" },
  { key: "checkout", label: "Checkout flow", meta: "10", icon: "creditCard" },
  { key: "icons", label: "Lumina icons", meta: "06", icon: "spark" },
  { key: "theming", label: "Theming", meta: "07", icon: "palette" },
  { key: "motion", label: "Motion", meta: "08", icon: "motion" },
  { key: "accessibility", label: "Accessibility", meta: "09", icon: "accessibility" },
];

const iconNames: IconName[] = ["spark", "grid", "layers", "code", "palette", "motion", "accessibility", "home", "user", "settings", "bell", "heart", "star", "lock", "calendar", "download", "upload", "globe", "github", "google", "x", "facebook", "linkedin", "instagram", "youtube", "discord", "slack", "tiktok", "apple", "microsoft", "shopify", "stripe", "paypal", "visa", "mastercard", "command", "folder", "database", "monitor", "tablet", "phone", "dashboard", "chart", "wallet", "cart", "bag", "package", "truck", "receipt", "tag", "percent", "creditCard", "heartPlus", "compare", "return", "warehouse", "barcode", "qr", "coupon", "gift", "storefront", "mapPin", "headset", "review", "filter", "sort", "edit", "trash", "eye", "eyeOff", "mail", "message", "help", "info", "warning", "success", "clock", "logout", "refresh", "activity", "gauge", "users", "arrow", "check", "menu", "sun", "moon"];
const codeSnippets: Record<string, string> = {
  css: '<link rel="stylesheet" href="https://cdn.jsdelivr.net/gh/Godszeal/lumina-css/client/public/lumina.css" />',
  js: '<script defer src="https://cdn.jsdelivr.net/gh/Godszeal/lumina-css/client/public/lumina.js"></script>',
  grid: '<div class="lu-grid lu-grid-3 lu-gap-4">\n  <article class="lu-card">One</article>\n  <article class="lu-card">Two</article>\n</div>',
  icons: '<span data-lu-icon="dashboard" aria-label="Dashboard"></span>',
};

function SectionLabel({ index, children }: { index: string; children: string }) {
  return <div className="flex items-center gap-3 text-[10px] font-semibold uppercase tracking-[0.18em] text-muted-foreground"><span className="font-mono text-[#315CFF]">{index}</span><span className="relative flex h-4 w-5 items-center"><span className="absolute h-px w-8 bg-[#315CFF]/40" /><span className="absolute left-1 h-3 w-1 rotate-[32deg] bg-[#315CFF]" /></span><span>{children}</span></div>;
}

function CopyCode({ value }: { value: string }) {
  const [copied, setCopied] = useState(false);
  return <button className="flex shrink-0 items-center gap-2 rounded-full border border-border px-3 py-2 font-mono text-[9px] uppercase tracking-widest text-muted-foreground transition hover:border-[#315CFF] hover:text-[#315CFF]" onClick={() => { navigator.clipboard?.writeText(value); setCopied(true); window.setTimeout(() => setCopied(false), 1300); }}><Copy size={12} />{copied ? "Copied" : "Copy"}</button>;
}

function CodeBlock({ value }: { value: string }) {
  return <div className="overflow-hidden border border-border bg-foreground text-background lu-shadow"><div className="flex items-center justify-between border-b border-background/10 px-4 py-3"><span className="font-mono text-[9px] uppercase tracking-widest text-background/50">lumina snippet</span><CopyCode value={value} /></div><pre className="overflow-x-auto p-5 font-mono text-[11px] leading-7 text-background/85"><code>{value}</code></pre></div>;
}

export default function Home() {
  const [active, setActive] = useState<SectionKey>("overview");
  const [query, setQuery] = useState("");
  const [mobileOpen, setMobileOpen] = useState(false);
  const [dark, setDark] = useState(() => typeof window !== "undefined" && (localStorage.getItem("lu-theme") === "dark" || (!localStorage.getItem("lu-theme") && window.matchMedia?.("(prefers-color-scheme: dark)").matches)));
  const [gridOn, setGridOn] = useState(() => typeof window === "undefined" || localStorage.getItem("lu-grid") !== "off");
  const [iconTone, setIconTone] = useState<"paper" | "ink" | "cobalt">("paper");
  useEffect(() => { document.documentElement.dataset.luTheme = dark ? "dark" : "light"; localStorage.setItem("lu-theme", dark ? "dark" : "light"); }, [dark]);
  useEffect(() => { document.documentElement.dataset.luGrid = gridOn ? "on" : "off"; localStorage.setItem("lu-grid", gridOn ? "on" : "off"); }, [gridOn]);
  const filteredNav = useMemo(() => nav.filter((item) => `${item.label} ${item.meta}`.toLowerCase().includes(query.toLowerCase())), [query]);
  const go = (key: SectionKey) => { setActive(key); setMobileOpen(false); window.scrollTo({ top: 0, behavior: "smooth" }); };
  const current = nav.find((item) => item.key === active) ?? nav[0];

  return <div className={`${dark ? "dark " : ""}${gridOn ? "" : "lu-no-grid "}lu-shell`}>
    <div className="relative z-10 min-h-screen lg:grid lg:grid-cols-[292px_1fr]">
      <aside className="hidden border-r border-border/80 bg-background/90 lg:flex lg:flex-col">
        <div className="flex items-center gap-3 border-b border-border/80 px-7 py-6"><div className="relative flex h-10 w-10 items-center justify-center bg-[#315CFF] text-white shadow-[4px_4px_0_#111827]"><span className="absolute h-5 w-2 rotate-[32deg] bg-white" /><span className="absolute bottom-2 left-2 h-2 w-5 bg-white" /></div><div><div className="flex items-center gap-1 font-display text-sm font-bold tracking-[-.04em]"><span>LUMINA</span><span className="relative mx-0.5 inline-flex h-4 w-3 items-center"><span className="absolute left-1 h-5 w-1 -rotate-[32deg] bg-[#315CFF]" /></span><span>CSS</span></div><div className="font-mono text-[9px] uppercase tracking-widest text-muted-foreground">Documentation / 0.4</div></div></div>
        <div className="border-b border-border/80 p-5"><label className="flex items-center gap-2 border border-border bg-card px-3 py-2.5 text-muted-foreground focus-within:border-[#315CFF]"><Search size={14} /><input aria-label="Search documentation" value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search docs" className="w-full bg-transparent font-mono text-[10px] outline-none placeholder:text-muted-foreground" /><span className="font-mono text-[9px]">⌘K</span></label></div>
        <nav className="flex-1 overflow-auto p-4">{filteredNav.map((item) => <button key={item.key} onClick={() => go(item.key)} className={`group mb-1 flex w-full items-center gap-3 border-l-2 px-3 py-3 text-left transition ${active === item.key ? "border-[#315CFF] bg-[#315CFF]/8 text-foreground" : "border-transparent text-muted-foreground hover:border-border hover:text-foreground"}`}><LuminaIcon name={item.icon} size={16} className={active === item.key ? "text-[#315CFF]" : ""} /><span className="flex-1 text-xs font-semibold">{item.label}</span><span className="font-mono text-[9px] text-muted-foreground">{item.meta}</span></button>)}</nav>
        <div className="border-t border-border/80 p-5"><div className="mb-4 flex items-center justify-between"><span className="font-mono text-[9px] uppercase tracking-widest text-muted-foreground">System status</span><span className="h-2 w-2 rounded-full bg-[#c8f564] ring-4 ring-[#c8f564]/15" /></div><div className="font-mono text-[10px] leading-6 text-muted-foreground">All primitives loaded.<br /><span className="text-foreground">Ready for composition.</span></div></div>
      </aside>

      <main className="min-w-0">
        <header className="sticky top-0 z-40 flex items-center justify-between border-b border-border/80 bg-background/90 px-4 py-3 backdrop-blur-xl sm:px-6 lg:px-10"><button className="flex items-center gap-3 lg:hidden" onClick={() => setMobileOpen(true)}><LuminaIcon name="menu" size={20} /><span className="flex items-center gap-1 font-display text-sm font-bold tracking-[-.04em]"><span>LUMINA</span><span className="relative inline-flex h-4 w-3 items-center"><span className="absolute left-1 h-5 w-1 -rotate-[32deg] bg-[#315CFF]" /></span><span>CSS</span></span></button><div className="hidden items-center gap-3 lg:flex"><span className="font-mono text-[10px] uppercase tracking-widest text-muted-foreground">Docs /</span><span className="font-mono text-[10px] uppercase tracking-widest text-[#315CFF]">{current.label}</span></div><div className="flex items-center gap-2"><span className="hidden font-mono text-[9px] uppercase tracking-widest text-muted-foreground sm:block">v0.9.0 / stable</span><button onClick={() => setDark(!dark)} className="rounded-full border border-border p-2 text-muted-foreground transition hover:border-[#315CFF] hover:text-[#315CFF]" aria-label="Toggle dark mode"><LuminaIcon name={dark ? "sun" : "moon"} size={15} /></button><button onClick={() => setGridOn(!gridOn)} className="rounded-full border border-border p-2 text-muted-foreground transition hover:border-[#315CFF] hover:text-[#315CFF]" aria-label={gridOn ? "Hide grid background" : "Show grid background"}><LuminaIcon name={gridOn ? "grid" : "close"} size={15} /></button><a href="#install" onClick={(e) => { e.preventDefault(); go("install"); }} className="rounded-full bg-[#315CFF] px-4 py-2.5 font-mono text-[10px] font-semibold uppercase tracking-widest text-white transition hover:-translate-y-0.5">Install <span className="ml-1">↗</span></a></div></header>

        {mobileOpen && <div className="fixed inset-0 z-50 bg-foreground/40 lg:hidden" onClick={() => setMobileOpen(false)}><div className="h-full w-[min(88vw,350px)] bg-background p-5 shadow-2xl" onClick={(e) => e.stopPropagation()}><div className="mb-8 flex items-center justify-between"><span className="font-display text-lg font-bold">LUMINA<span className="text-[#315CFF]">.</span>CSS</span><button onClick={() => setMobileOpen(false)} aria-label="Close navigation"><LuminaIcon name="close" /></button></div><label className="mb-5 flex items-center gap-2 border border-border px-3 py-3 text-muted-foreground"><Search size={15} /><input aria-label="Search documentation" value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search docs" className="w-full bg-transparent font-mono text-[10px] outline-none" /></label>{filteredNav.map((item) => <button key={item.key} onClick={() => go(item.key)} className={`mb-1 flex w-full items-center gap-3 border-l-2 px-3 py-3 text-left ${active === item.key ? "border-[#315CFF] bg-[#315CFF]/8" : "border-transparent text-muted-foreground"}`}><LuminaIcon name={item.icon} size={16} /><span className="flex-1 text-sm font-semibold">{item.label}</span><span className="font-mono text-[9px] text-muted-foreground">{item.meta}</span></button>)}</div></div>}

        <div className="mx-auto max-w-[1180px] px-4 py-9 sm:px-6 lg:px-12 lg:py-14">
          {active === "overview" && <Overview onNavigate={go} />}
          {active === "install" && <Install />}
          {active === "foundations" && <Foundations />}
          {active === "layout" && <LayoutDocs />}
          {active === "components" && <ComponentsDocs />}
          {active === "samples" && <SamplesDocs />}
          {active === "dashboard" && <DashboardDocs />}
          {active === "admin" && <AdminKitDocs />}
          {active === "api" && <ApiReferenceDocs />}
          {active === "commerce" && <CommerceDocs />}
          {active === "checkout" && <CheckoutDocs />}
          {active === "icons" && <IconsDocs tone={iconTone} setTone={setIconTone} />}
          {active === "theming" && <Theming />}
          {active === "motion" && <MotionDocs />}
          {active === "accessibility" && <AccessibilityDocs />}
        </div>
        <footer className="border-t border-border/80 px-4 py-8 sm:px-6 lg:px-12"><div className="mx-auto flex max-w-[1180px] flex-col gap-3 font-mono text-[9px] uppercase tracking-widest text-muted-foreground sm:flex-row sm:justify-between"><span>Built for the open web / Lumina CSS</span><span>MIT / v0.9.0 / CDN ready</span></div></footer>
      </main>
    </div>
  </div>;
}

function DocsHeader({ index, eyebrow, title, body }: { index: string; eyebrow: string; title: string; body: string }) { return <div className="max-w-3xl"><SectionLabel index={index} children={eyebrow} /><h1 className="lu-display mt-6 text-[clamp(3rem,7vw,6.6rem)] font-bold leading-[.88] tracking-[-.06em]">{title}</h1><p className="mt-7 max-w-2xl text-base leading-8 text-muted-foreground sm:text-lg">{body}</p></div>; }
function DocCard({ title, children, icon }: { title: string; children: React.ReactNode; icon?: IconName }) { return <div className="group border border-border border-t-2 border-t-[#315CFF]/60 bg-card p-5 transition hover:-translate-y-1 hover:shadow-[7px_7px_0_#315CFF]">{icon && <LuminaIcon name={icon} size={20} className="mb-8 text-[#315CFF]" />}<h3 className="font-display text-lg font-semibold">{title}</h3><div className="mt-3 text-sm leading-7 text-muted-foreground">{children}</div></div>; }
function Overview({ onNavigate }: { onNavigate: (key: SectionKey) => void }) { return <><section className="relative overflow-hidden border-b border-border pb-16 lg:pb-24"><img src="/manus-storage/lumina-hero-texture_ee04af89.png" alt="" className="pointer-events-none absolute inset-0 h-full w-full object-cover opacity-30 mix-blend-multiply dark:opacity-15 dark:mix-blend-screen" /><div className="relative"><SectionLabel index="00" children="A new baseline for the web" /><h1 className="lu-display mt-7 max-w-5xl text-[clamp(4rem,11vw,10rem)] font-bold leading-[.84] tracking-[-.07em]">Build with<br /><span className="text-[#315CFF]">signal.</span></h1><p className="mt-9 max-w-2xl text-lg leading-8 text-muted-foreground">Lumina is a hybrid styling CDN for builders who want the speed of utilities, the clarity of components, and a visual language that feels authored.</p><div className="mt-9 flex flex-wrap gap-3"><button onClick={() => onNavigate("install")} className="rounded-full bg-foreground px-5 py-3.5 font-mono text-xs font-semibold uppercase tracking-widest text-background transition hover:-translate-y-1">Install Lumina ↗</button><button onClick={() => onNavigate("icons")} className="rounded-full border border-border px-5 py-3.5 font-mono text-xs font-semibold uppercase tracking-widest transition hover:border-[#315CFF] hover:text-[#315CFF]">Meet the icons</button></div><div className="mt-12 max-w-2xl border border-border bg-foreground p-4 text-background lu-shadow"><div className="mb-3 flex items-center justify-between font-mono text-[9px] uppercase tracking-widest text-background/50"><span>First signal / 00</span><span className="text-[#c8f564]">ready</span></div><code className="block overflow-x-auto whitespace-nowrap font-mono text-[11px] leading-7 text-background/85">&lt;link rel="stylesheet" href="https://cdn.jsdelivr.net/gh/Godszeal/lumina-css/client/public/lumina.css" /&gt;</code></div></div></section><section className="border-b border-border py-14 lg:py-20"><SectionLabel index="01" children="Why Lumina" /><div className="mt-8 grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><DocCard title="Readable utilities" icon="code">Classes are short, composable, and prefixed with <code className="text-[#315CFF]">lu-</code> so they stay clear beside your own CSS.</DocCard><DocCard title="Responsive by default" icon="grid">Core layout primitives collapse gracefully on small screens without requiring a second mental model.</DocCard><DocCard title="A real icon language" icon="spark">Geometric SVG symbols have a shared stroke, soft depth, and quiet visual personality.</DocCard><DocCard title="No build step" icon="layers">Drop in the stylesheet from a CDN. Add the script only when progressive enhancement helps.</DocCard></div></section><section className="py-14 lg:py-20"><div className="grid gap-8 lg:grid-cols-[.7fr_1.3fr] lg:items-end"><div><SectionLabel index="02" children="The map" /><h2 className="lu-display mt-5 text-4xl font-bold leading-none lg:text-6xl">Everything<br /><span className="text-[#315CFF]">in one route.</span></h2></div><div className="grid gap-3 sm:grid-cols-2"><button onClick={() => onNavigate("layout")} className="text-left"><DocCard title="Layout utilities" icon="grid">Grid, flex, gap, alignment, spacing, width, and responsive helpers for building the frame.</DocCard></button><button onClick={() => onNavigate("components")} className="text-left"><DocCard title="Components" icon="layers">Buttons, cards, badges, inputs, dividers, and surfaces with token-aware variants.</DocCard></button><button onClick={() => onNavigate("theming")} className="text-left"><DocCard title="Theming" icon="palette">CSS variables make the system yours without fighting the defaults.</DocCard></button><button onClick={() => onNavigate("accessibility")} className="text-left"><DocCard title="Accessible intent" icon="accessibility">Focus rings, reduced motion, semantic guidance, and contrast-minded defaults.</DocCard></button></div></div></section></>; }
function Install() { return <><DocsHeader index="01" eyebrow="Installation" title="One import. Whole language." body="Lumina is intentionally easy to adopt. The CSS layer is enough for layout, surfaces, icons, and motion. The optional script adds theme persistence and copy helpers." /><div className="mt-12 grid gap-6 lg:grid-cols-2"><div><div className="mb-3 flex items-center justify-between"><span className="font-mono text-[10px] uppercase tracking-widest text-muted-foreground">01 / stylesheet</span><span className="rounded-full bg-[#c8f564] px-2 py-1 font-mono text-[9px] font-semibold">REQUIRED</span></div><CodeBlock value={codeSnippets.css} /></div><div><div className="mb-3 flex items-center justify-between"><span className="font-mono text-[10px] uppercase tracking-widest text-muted-foreground">02 / enhancement</span><span className="rounded-full border border-border px-2 py-1 font-mono text-[9px] font-semibold text-muted-foreground">OPTIONAL</span></div><CodeBlock value={codeSnippets.js} /></div></div><div className="mt-8 grid gap-3 sm:grid-cols-3"><DocCard title="1. Link">Add the stylesheet in your document head.</DocCard><DocCard title="2. Compose">Use prefixed utilities and components in your markup.</DocCard><DocCard title="3. Extend">Override the CSS variables when your brand needs a new signal.</DocCard></div></>; }
function Foundations() { return <><DocsHeader index="02" eyebrow="Foundations" title="The tokens are the tone." body="Lumina ships with a warm paper canvas, ink-charcoal typography, Cobalt Signal actions, and acid-lime status states. Everything is exposed as a custom property." /><div className="mt-12 grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><DocCard title="Cobalt Signal"><span className="mb-4 block h-12 bg-[#315CFF]" /><code className="text-[#315CFF]">--lu-cobalt: #315CFF</code></DocCard><DocCard title="Paper"><span className="mb-4 block h-12 border border-border bg-[#f7f7f3]" /><code>--lu-paper: #F7F7F3</code></DocCard><DocCard title="Ink"><span className="mb-4 block h-12 bg-[#111827]" /><code>--lu-ink: #111827</code></DocCard><DocCard title="Ready"><span className="mb-4 block h-12 bg-[#c8f564]" /><code>status only / #C8F564</code></DocCard></div><div className="mt-10 border border-border bg-card p-6"><SectionLabel index="02A" children="Typography" /><div className="mt-8 grid gap-6 md:grid-cols-3"><div><div className="font-display text-4xl font-bold">Space Grotesk</div><p className="mt-2 text-sm text-muted-foreground">Display and headings. Tight, technical, expressive.</p></div><div><div className="text-2xl font-semibold">DM Sans</div><p className="mt-2 text-sm text-muted-foreground">Body copy. Neutral, readable, generous.</p></div><div><div className="font-mono text-xl">IBM Plex Mono</div><p className="mt-2 text-sm text-muted-foreground">Code, labels, metadata, and system status.</p></div></div></div></>; }
function LayoutDocs() { return <><DocsHeader index="03" eyebrow="Layout utilities" title="Frame the idea." body="Start with structure. Lumina’s layout primitives are small enough to memorize and expressive enough to build a full interface without a dependency chain." /><div className="mt-12 grid gap-8 lg:grid-cols-[1fr_.8fr]"><div><CodeBlock value={codeSnippets.grid} /><div className="mt-4 grid grid-cols-3 gap-3"><div className="border border-[#315CFF] bg-[#315CFF]/10 p-5 font-mono text-[10px] text-[#315CFF]">ONE</div><div className="border border-[#315CFF] bg-[#315CFF]/10 p-5 font-mono text-[10px] text-[#315CFF]">TWO</div><div className="border border-[#315CFF] bg-[#315CFF]/10 p-5 font-mono text-[10px] text-[#315CFF]">THREE</div></div></div><div className="space-y-3"><DocCard title="Grid" icon="grid"><code className="text-[#315CFF]">lu-grid</code> plus <code className="text-[#315CFF]">lu-grid-2/3/4</code> handles the main axis of your page.</DocCard><DocCard title="Flex" icon="layers"><code className="text-[#315CFF]">lu-flex</code>, alignment helpers, wrapping, and gap tokens keep smaller compositions fluid.</DocCard><DocCard title="Responsive rule" icon="arrow">At 760px, multi-column utility grids collapse to one column for a calm mobile reading order.</DocCard></div></div><div className="mt-12 border-t border-border pt-10"><SectionLabel index="03A" children="Advanced grid recipes" /><div className="mt-6 grid gap-6 lg:grid-cols-2"><div><CodeBlock value={'<section class="lu-grid lu-grid-editorial lu-gap-6">\n  <article>Seven columns</article>\n  <article>Five columns</article>\n  <article>Offset six</article>\n</section>'} /><div className="lu-grid lu-grid-editorial lu-gap-3 mt-4"><div className="border border-[#315CFF] bg-[#315CFF]/10 p-4 font-mono text-[9px] text-[#315CFF]">7 COL</div><div className="border border-[#315CFF] bg-[#315CFF]/10 p-4 font-mono text-[9px] text-[#315CFF]">5 COL</div><div className="border border-[#315CFF] bg-[#315CFF]/10 p-4 font-mono text-[9px] text-[#315CFF]">OFFSET / 6</div></div></div><div><CodeBlock value={'<div class="lu-grid lu-grid-12 lu-gap-4">\n  <aside class="lu-col-span-3">Rail</aside>\n  <main class="lu-col-span-6">Main</main>\n  <aside class="lu-col-span-3">Aside</aside>\n</div>'} /><div className="lu-grid lu-grid-12 lu-gap-3 mt-4"><div className="lu-col-span-3 border border-[#c8f564] bg-[#c8f564]/20 p-4 font-mono text-[9px]">RAIL</div><div className="lu-col-span-6 border border-[#315CFF] bg-[#315CFF]/10 p-4 font-mono text-[9px] text-[#315CFF]">MAIN</div><div className="lu-col-span-3 border border-border bg-card p-4 font-mono text-[9px]">ASIDE</div></div></div></div><div className="mt-6 grid gap-3 sm:grid-cols-3"><DocCard title="Auto-fit" icon="grid"><code className="text-[#315CFF]">lu-grid-auto</code> fills available space with a minimum track size.</DocCard><DocCard title="Editorial" icon="layers"><code className="text-[#315CFF]">lu-grid-editorial</code> alternates wide, narrow, and offset spans.</DocCard><DocCard title="Masonry-like" icon="spark"><code className="text-[#315CFF]">lu-grid-masonry</code> uses row spans for visual rhythm without JavaScript.</DocCard></div></div></>; }
function ComponentsDocs() { return <><DocsHeader index="04" eyebrow="Components" title="Useful by default." body="Components are intentionally low ceremony. Use a base class, add a modifier, and keep your own markup in control." /><div className="mt-12 grid gap-6 lg:grid-cols-2"><div className="space-y-4"><div className="flex flex-wrap gap-3"><button className="lu-btn lu-btn-primary">Primary action <LuminaIcon name="arrow" size={14} /></button><button className="lu-btn lu-btn-outline">Outline action</button><span className="lu-badge">READY</span></div><input className="lu-input" placeholder="lu-input / focus me" /><div className="lu-card lu-shadow"><div className="flex items-center justify-between"><span className="font-mono text-[10px] uppercase tracking-widest text-muted-foreground">lu-card</span><LuminaIcon name="spark" className="text-[#315CFF]" /></div><h3 className="mt-8 font-display text-2xl font-bold">A surface with signal.</h3><p className="mt-2 text-sm leading-7 text-muted-foreground">The base surface is quiet. The modifiers decide how much personality it carries.</p></div></div><CodeBlock value={'<button class="lu-btn lu-btn-primary">Action</button>\n<span class="lu-badge">READY</span>\n<article class="lu-card lu-shadow">...</article>'} /></div></>; }
function IconsDocs({ tone, setTone }: { tone: "paper" | "ink" | "cobalt"; setTone: (tone: "paper" | "ink" | "cobalt") => void }) { return <><DocsHeader index="06" eyebrow="Lumina icons" title="A softer signal." body="Lumina icons are inline SVG symbols, not a font. They share a geometric vocabulary, keep their own accessible labels, and inherit the color of the context they live in." /><div className="mt-10 flex flex-wrap items-center gap-2"><span className="font-mono text-[10px] uppercase tracking-widest text-muted-foreground">Preview tone</span>{(["paper", "ink", "cobalt"] as const).map((item) => <button key={item} onClick={() => setTone(item)} className={`rounded-full border px-3 py-2 font-mono text-[10px] uppercase tracking-widest transition ${tone === item ? "border-[#315CFF] bg-[#315CFF] text-white" : "border-border text-muted-foreground hover:border-[#315CFF]"}`}>{item}</button>)}</div><div className={`mt-8 grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-6 ${tone === "ink" ? "bg-foreground text-background" : tone === "cobalt" ? "bg-[#315CFF] text-white" : "bg-card text-foreground"} border border-border p-4 transition`}><div className="col-span-full mb-2 flex items-center justify-between font-mono text-[9px] uppercase tracking-widest text-current/60"><span>50 symbols / inline SVG</span><span>neumorphic family</span></div>{iconNames.map((name) => <div key={name} className="flex min-h-28 flex-col items-center justify-center gap-4 border border-current/10 bg-background/10 p-4 text-center"><div className="lu-neu-icon"><LuminaIcon name={name} size={25} /></div><span className="font-mono text-[9px] uppercase tracking-widest">{name}</span></div>)}</div><div className="mt-8 grid gap-6 lg:grid-cols-2"><CodeBlock value={codeSnippets.icons} /><div className="border border-border bg-card p-6"><SectionLabel index="06A" children="Why SVG" /><p className="mt-5 text-sm leading-7 text-muted-foreground">SVG keeps the symbol crisp at every size, inherits CSS color, supports `aria-hidden` or a visible label, and avoids the baseline and loading tradeoffs of an icon font.</p><div className="mt-6 flex items-center gap-3 rounded-sm border border-border bg-background p-4"><LuminaIcon name="accessibility" className="text-[#315CFF]" /><span className="font-mono text-[10px]">Icons should clarify intent, not become the intent.</span></div></div></div></>; }
function SamplesDocs() {
  const [menuOpen, setMenuOpen] = useState(false);
  const [modalOpen, setModalOpen] = useState(false);
  return <><DocsHeader index="05" eyebrow="Samples & previews" title="See the signal move." body="Copy the markup, open the preview, and keep the interaction model small. Lumina’s dropdowns and modals are accessible, CDN-friendly, and responsive without a component framework." /><div className="mt-12 grid gap-8 lg:grid-cols-2"><div className="lu-card lu-shadow p-6"><div className="flex items-center justify-between"><div><div className="font-mono text-[10px] uppercase tracking-widest text-muted-foreground">Preview 01</div><h3 className="mt-2 font-display text-2xl font-bold">Dropdown menu</h3></div><LuminaIcon name="filter" className="text-[#315CFF]" /></div><div className="mt-10 flex min-h-32 items-start justify-end"><div className="lu-dropdown" data-lu-open={menuOpen ? "true" : "false"}><button onClick={() => setMenuOpen(!menuOpen)} aria-expanded={menuOpen} className="lu-btn lu-btn-outline">Workspace <LuminaIcon name="arrow" size={14} /></button>{menuOpen && <div className="lu-dropdown-menu" data-lu-open="true"><button className="lu-dropdown-item"><LuminaIcon name="dashboard" size={15} />Overview</button><button className="lu-dropdown-item"><LuminaIcon name="users" size={15} />Members</button><button className="lu-dropdown-item"><LuminaIcon name="settings" size={15} />Settings</button></div>}</div></div><CodeBlock value={'<div class="lu-dropdown" data-lu-dropdown>\n  <button data-lu-dropdown-trigger aria-expanded="false">Workspace</button>\n  <div class="lu-dropdown-menu">...</div>\n</div>'} /></div><div className="lu-card lu-shadow p-6"><div className="flex items-center justify-between"><div><div className="font-mono text-[10px] uppercase tracking-widest text-muted-foreground">Preview 02</div><h3 className="mt-2 font-display text-2xl font-bold">Modal dialog</h3></div><LuminaIcon name="gauge" className="text-[#315CFF]" /></div><div className="mt-10 flex min-h-32 items-start"><button onClick={() => setModalOpen(true)} className="lu-btn lu-btn-primary">Open modal <LuminaIcon name="arrow" size={14} /></button></div><CodeBlock value={'<button data-lu-modal-open="#lu-modal">Open modal</button>\n<div id="lu-modal" data-lu-modal aria-hidden="true">...</div>'} /></div></div>{modalOpen && <div className="lu-modal" data-lu-open="true" aria-hidden="false"><div className="lu-modal-backdrop" onClick={() => setModalOpen(false)} /><div className="lu-modal-panel p-7" role="dialog" aria-modal="true" aria-labelledby="sample-modal-title"><button onClick={() => setModalOpen(false)} className="lu-modal-close" aria-label="Close modal"><LuminaIcon name="close" size={16} /></button><div className="lu-neu-icon"><LuminaIcon name="success" className="text-[#315CFF]" /></div><h3 id="sample-modal-title" className="mt-6 font-display text-3xl font-bold">Signal confirmed.</h3><p className="mt-3 max-w-prose text-sm leading-7 text-muted-foreground">This is a responsive Lumina modal. It traps attention, keeps a clear escape route, and collapses cleanly on small screens.</p><button onClick={() => setModalOpen(false)} className="lu-btn lu-btn-primary mt-7">Continue</button></div></div>}<div className="mt-10 border border-border bg-card p-6"><SectionLabel index="05A" children="Dashboard icon proof" /><div className="mt-6 grid grid-cols-3 gap-3 sm:grid-cols-6">{(["activity", "gauge", "users", "chart", "wallet", "success"] as IconName[]).map((name) => <div key={name} className="lu-neu-icon"><LuminaIcon name={name} size={22} /></div>)}</div></div></>;
}

type DashboardStatus = "All" | "Active" | "Review" | "Paused";
type DashboardRow = { id: string; workspace: string; owner: string; status: Exclude<DashboardStatus, "All">; usage: string; updated: string; trend: string };
const dashboardRows: DashboardRow[] = [
  { id: "LM-1042", workspace: "Northstar", owner: "Product systems", status: "Active", usage: "84%", updated: "2 min ago", trend: "+12.4%" },
  { id: "LM-1041", workspace: "Atlas board", owner: "Operations", status: "Review", usage: "61%", updated: "18 min ago", trend: "+4.8%" },
  { id: "LM-1040", workspace: "Field notes", owner: "Research lab", status: "Active", usage: "92%", updated: "42 min ago", trend: "+18.1%" },
  { id: "LM-1039", workspace: "Signal room", owner: "Design ops", status: "Paused", usage: "38%", updated: "1 hr ago", trend: "-2.2%" },
  { id: "LM-1038", workspace: "Waypoint", owner: "Growth team", status: "Active", usage: "73%", updated: "2 hrs ago", trend: "+8.6%" },
  { id: "LM-1037", workspace: "Ledger view", owner: "Finance ops", status: "Review", usage: "47%", updated: "3 hrs ago", trend: "+1.6%" },
  { id: "LM-1036", workspace: "Launchpad", owner: "Release team", status: "Active", usage: "88%", updated: "5 hrs ago", trend: "+11.2%" },
  { id: "LM-1035", workspace: "Quiet hours", owner: "People ops", status: "Paused", usage: "22%", updated: "1 day ago", trend: "-6.4%" },
];

function DashboardDocs() {
  const [search, setSearch] = useState("");
  const [status, setStatus] = useState<DashboardStatus>("All");
  const [page, setPage] = useState(1);
  const [sortAsc, setSortAsc] = useState(false);
  const pageSize = 5;
  const filtered = useMemo(() => dashboardRows.filter((row) => (status === "All" || row.status === status) && `${row.workspace} ${row.owner} ${row.id}`.toLowerCase().includes(search.toLowerCase())).sort((a, b) => sortAsc ? a.workspace.localeCompare(b.workspace) : b.workspace.localeCompare(a.workspace)), [search, status, sortAsc]);
  const pageCount = Math.max(1, Math.ceil(filtered.length / pageSize));
  const visible = filtered.slice((page - 1) * pageSize, page * pageSize);
  useEffect(() => { setPage(1); }, [search, status]);
  return <><DocsHeader index="06" eyebrow="Dashboard showcase" title="A calm control room." body="A complete dashboard recipe for internal products: compact metrics, filterable data, predictable table geometry, status semantics, pagination, and a useful empty state when the query has no match." /><div className="mt-10 grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><DocCard title="Active workspaces" icon="activity"><strong className="font-display text-3xl text-foreground">24</strong><span className="ml-2 text-[#356b16]">+12.4%</span></DocCard><DocCard title="System health" icon="gauge"><strong className="font-display text-3xl text-foreground">98.6%</strong><span className="ml-2 text-[#356b16]">nominal</span></DocCard><DocCard title="Contributors" icon="users"><strong className="font-display text-3xl text-foreground">148</strong><span className="ml-2 text-muted-foreground">this cycle</span></DocCard><DocCard title="Pending review" icon="warning"><strong className="font-display text-3xl text-foreground">07</strong><span className="ml-2 text-muted-foreground">needs a look</span></DocCard></div><section className="lu-table-shell mt-10 bg-card lu-shadow"><div className="lu-filter-bar flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between"><div><SectionLabel index="06A" children="Workspace table" /><p className="mt-2 text-sm text-muted-foreground">Demo data only / no customer information</p></div><div className="flex flex-col gap-2 sm:flex-row"><label className="flex items-center gap-2 border border-border bg-background px-3 py-2"><LuminaIcon name="search" size={14} className="text-muted-foreground" /><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search workspaces" aria-label="Search workspaces" className="lu-filter-control w-full bg-transparent font-mono text-[10px] outline-none sm:w-40" /></label><select value={status} onChange={(event) => setStatus(event.target.value as DashboardStatus)} aria-label="Filter by status" className="lu-filter-control border border-border bg-background px-3 py-2 font-mono text-[10px] uppercase tracking-widest outline-none focus:border-[#315CFF]"><option>All</option><option>Active</option><option>Review</option><option>Paused</option></select></div></div><div className="overflow-x-auto"><table className="lu-table lu-table-fixed w-full min-w-[720px] text-left"><thead className="border-b border-border bg-background"><tr className="font-mono text-[9px] uppercase tracking-widest text-muted-foreground"><th className="w-[16%] px-4 py-3">ID</th><th className="w-[24%] px-4 py-3"><button onClick={() => setSortAsc(!sortAsc)} className="inline-flex items-center gap-2 hover:text-[#315CFF]" aria-label="Sort workspaces">Workspace <LuminaIcon name="sort" size={12} /></button></th><th className="w-[20%] px-4 py-3">Owner</th><th className="w-[14%] px-4 py-3">Status</th><th className="w-[13%] px-4 py-3">Usage</th><th className="w-[13%] px-4 py-3">Updated</th></tr></thead><tbody className="divide-y divide-border">{visible.map((row) => <tr key={row.id} className="group hover:bg-[#315CFF]/[.035]"><td className="px-4 py-4 font-mono text-[10px] text-muted-foreground">{row.id}</td><td className="px-4 py-4"><div className="font-semibold">{row.workspace}</div><div className="mt-1 font-mono text-[9px] text-[#356b16]">{row.trend}</div></td><td className="px-4 py-4 text-sm text-muted-foreground">{row.owner}</td><td className="px-4 py-4"><span className={`inline-flex items-center gap-2 rounded-full border px-2 py-1 font-mono text-[9px] uppercase tracking-widest ${row.status === "Active" ? "border-[#c8f564]/60 bg-[#c8f564]/20 text-[#356b16]" : row.status === "Review" ? "border-[#315CFF]/25 bg-[#315CFF]/10 text-[#315CFF]" : "border-border text-muted-foreground"}`}><span className="lu-status-dot" />{row.status}</span></td><td className="px-4 py-4 font-mono text-[10px]">{row.usage}</td><td className="px-4 py-4 font-mono text-[10px] text-muted-foreground">{row.updated}</td></tr>)}</tbody></table>{visible.length === 0 && <div className="lu-empty px-6 py-16 text-center"><div className="mx-auto lu-neu-icon"><LuminaIcon name="search" className="text-[#315CFF]" /></div><h3 className="mt-5 font-display text-2xl font-bold">No signal found.</h3><p className="mx-auto mt-2 max-w-md text-sm leading-7 text-muted-foreground">Try a different workspace name or reset the status filter to bring the table back into view.</p><button onClick={() => { setSearch(""); setStatus("All"); }} className="lu-btn lu-btn-outline mt-6">Reset filters</button></div>}</div><div className="lu-pagination flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><span className="font-mono text-[9px] uppercase tracking-widest text-muted-foreground">{filtered.length} results / page {page} of {pageCount}</span><div className="flex items-center gap-2"><button disabled={page <= 1} onClick={() => setPage((value) => Math.max(1, value - 1))} className="lu-btn lu-btn-outline px-3 py-2 disabled:cursor-not-allowed disabled:opacity-40"><LuminaIcon name="arrow" size={13} className="rotate-180" />Prev</button><button disabled={page >= pageCount} onClick={() => setPage((value) => Math.min(pageCount, value + 1))} className="lu-btn lu-btn-outline px-3 py-2 disabled:cursor-not-allowed disabled:opacity-40">Next<LuminaIcon name="arrow" size={13} /></button></div></div></section><div className="mt-8 grid gap-3 sm:grid-cols-3"><DocCard title="Table geometry" icon="grid">Use a fixed table layout on wide screens and a scroll shell on small screens so columns stay predictable.</DocCard><DocCard title="State semantics" icon="success">Pair status color with labels and icons so meaning survives low-vision and non-color contexts.</DocCard><DocCard title="Empty by design" icon="search">An empty state is a useful endpoint, not a failure. Keep the reset action close to the explanation.</DocCard></div><div className="mt-8"><CodeBlock value={'<div class="lu-table-shell lu-overflow-auto">\n  <table class="lu-table lu-table-fixed">...</table>\n</div>\n<nav class="lu-pagination">...</nav>'} /></div></>;
}

function AdminKitDocs() {
  const [tab, setTab] = useState("profile");
  const [drawer, setDrawer] = useState(false);
  const [command, setCommand] = useState(false);
  const [toast, setToast] = useState(false);
  return <><DocsHeader index="07" eyebrow="Admin Kit" title="The interface around the data." body="Lumina’s Admin Kit turns the framework into a complete application surface: forms, tabs, drawers, toasts, skeletons, and a command palette that share the same tokens and responsive behavior." /><div className="mt-10 grid gap-6 lg:grid-cols-2"><div className="lu-card lu-shadow"><SectionLabel index="07A" children="Tabs + forms" /><div className="mt-5 lu-tabs" role="tablist"><button className="lu-tab" aria-selected={tab === "profile"} onClick={() => setTab("profile")}>Profile</button><button className="lu-tab" aria-selected={tab === "security"} onClick={() => setTab("security")}>Security</button><button className="lu-tab" aria-selected={tab === "notifications"} onClick={() => setTab("notifications")}>Notifications</button></div>{tab === "profile" && <div className="mt-6 space-y-4"><label className="block"><span className="lu-label">Display name</span><input className="lu-input" defaultValue="Lumina operator" /></label><label className="block"><span className="lu-label">Team role</span><select className="lu-select"><option>Design systems</option><option>Product operations</option></select><span className="lu-help">This role controls which workspace controls appear.</span></label><button onClick={() => setToast(true)} className="lu-btn lu-btn-primary">Save profile <LuminaIcon name="check" size={14} /></button></div>}{tab === "security" && <div className="mt-6 space-y-4"><label className="block"><span className="lu-label">Current password</span><input type="password" className="lu-input" placeholder="••••••••" /></label><label className="block"><span className="lu-label">New password</span><input type="password" className="lu-input" placeholder="Use 12+ characters" /></label><button className="lu-btn lu-btn-primary">Update password</button></div>}{tab === "notifications" && <div className="mt-6 space-y-4"><label className="flex items-center justify-between border border-border p-4"><span><strong className="block text-sm">Weekly digest</strong><span className="lu-help">A concise system report every Monday.</span></span><input type="checkbox" defaultChecked /></label><label className="flex items-center justify-between border border-border p-4"><span><strong className="block text-sm">Usage alerts</strong><span className="lu-help">Only alert when a workspace crosses 80%.</span></span><input type="checkbox" /></label></div>}</div><div className="lu-card lu-shadow"><SectionLabel index="07B" children="Application chrome" /><div className="mt-6 flex flex-wrap gap-3"><button onClick={() => setDrawer(true)} className="lu-btn lu-btn-outline"><LuminaIcon name="menu" size={14} />Open drawer</button><button onClick={() => setCommand(true)} className="lu-btn lu-btn-outline"><LuminaIcon name="command" size={14} />Command palette</button><button onClick={() => setToast(true)} className="lu-btn lu-btn-primary"><LuminaIcon name="bell" size={14} />Show toast</button></div><div className="mt-8 grid gap-3"><div className="lu-skeleton h-5 w-2/3" /><div className="lu-skeleton h-4 w-full" /><div className="lu-skeleton h-4 w-5/6" /><span className="lu-help">Skeletons use transform-only shimmer and stop under reduced motion.</span></div><CodeBlock value={'<button data-lu-drawer-open="#settings">Open drawer</button>\n<button data-lu-command-open="#commands">Command palette</button>\n<div class="lu-toast-viewport" data-lu-toast-root></div>'} /></div></div>{drawer && <div className="lu-drawer" data-lu-open="true"><div className="lu-drawer-backdrop" onClick={() => setDrawer(false)} /><aside className="lu-drawer-panel" role="dialog" aria-modal="true" aria-label="Settings drawer"><button onClick={() => setDrawer(false)} className="lu-btn lu-btn-outline"><LuminaIcon name="close" size={14} />Close</button><h3 className="mt-8 font-display text-3xl font-bold">Settings</h3><p className="mt-3 text-sm leading-7 text-muted-foreground">A mobile-friendly drawer for secondary navigation, filters, and settings.</p><div className="mt-8 space-y-3"><button className="lu-dropdown-item"><LuminaIcon name="user" size={16} />Account</button><button className="lu-dropdown-item"><LuminaIcon name="bell" size={16} />Notifications</button><button className="lu-dropdown-item"><LuminaIcon name="settings" size={16} />Preferences</button></div></aside></div>}{command && <div className="lu-command" data-lu-open="true"><div className="lu-command-backdrop" onClick={() => setCommand(false)} /><div className="lu-command-panel" role="dialog" aria-label="Command palette"><input autoFocus className="lu-command-input" placeholder="Type a command…" /><div className="lu-command-list"><button className="lu-command-item"><LuminaIcon name="dashboard" size={16} />Open dashboard</button><button className="lu-command-item"><LuminaIcon name="plus" size={16} />Create workspace</button><button className="lu-command-item"><LuminaIcon name="settings" size={16} />Open settings</button></div></div></div>}{toast && <div className="lu-toast-viewport"><div className="lu-toast" role="status"><LuminaIcon name="success" className="text-[#356b16]" /><div className="flex-1"><strong className="block text-sm">Changes saved.</strong><span className="lu-help">Your profile is ready for the next session.</span></div><button onClick={() => setToast(false)} aria-label="Dismiss notification"><LuminaIcon name="close" size={15} /></button></div></div>}</>;
}

const apiReferenceEntries = [
  ["lu-table-shell", "class", "dashboard", "Responsive overflow shell for data tables."], ["lu-table", "class", "dashboard", "Baseline table styling with borders and rows."], ["lu-filter-bar", "class", "dashboard", "Responsive filter and search toolbar."], ["lu-pagination", "class", "dashboard", "Aligned pagination footer."], ["lu-empty", "class", "dashboard", "Intentional zero-result surface."], ["lu-tabs", "class", "components", "Scrollable tablist container."], ["lu-input", "class", "forms", "Token-aware text input."], ["lu-skeleton", "class", "feedback", "Reduced-motion loading placeholder."], ["lu-drawer", "class", "interactions", "Slide-in secondary navigation panel."], ["lu-toast-viewport", "class", "interactions", "Viewport for transient notifications."], ["lu-command", "class", "interactions", "Searchable command palette overlay."], ["data-lu-icon", "attribute", "icons", "Renders inline SVG icons."], ["data-lu-theme-toggle", "attribute", "theme", "Persists light/dark mode."], ["data-lu-grid-toggle", "attribute", "theme", "Persists grid background visibility."]
] as const;
function ApiReferenceDocs() { const [query, setQuery] = useState(""); const filtered = apiReferenceEntries.filter(([name, kind, group, description]) => `${name} ${kind} ${group} ${description}`.toLowerCase().includes(query.toLowerCase())); return <><DocsHeader index="08" eyebrow="API reference" title="Search the language." body="A compact searchable index for the classes and data attributes that make the Admin Kit work. The full machine-readable index is available at /lumina-api.json." /><div className="mt-10 flex items-center gap-3 border border-border bg-card p-3"><LuminaIcon name="search" size={18} className="text-[#315CFF]" /><input value={query} onChange={(event) => setQuery(event.target.value)} aria-label="Search Lumina API" placeholder="Search classes, groups, or behavior" className="w-full bg-transparent text-sm outline-none" /></div><div className="mt-6 overflow-x-auto border border-border bg-card"><table className="lu-table lu-table-fixed w-full min-w-[700px]"><thead><tr><th>Name</th><th>Kind</th><th>Group</th><th>Description</th></tr></thead><tbody>{filtered.map(([name, kind, group, description]) => <tr key={name}><td><code className="text-[#315CFF]">{name}</code></td><td><span className="lu-badge">{kind}</span></td><td className="font-mono text-[10px] uppercase tracking-widest text-muted-foreground">{group}</td><td className="text-sm text-muted-foreground">{description}</td></tr>)}</tbody></table>{filtered.length === 0 && <div className="lu-empty">No API entries match <strong>{query}</strong>.</div>}</div><div className="mt-8"><CodeBlock value={'<link rel="stylesheet" href="https://cdn.jsdelivr.net/gh/Godszeal/lumina-css/client/public/lumina-core.css">\n<link rel="stylesheet" href="https://cdn.jsdelivr.net/gh/Godszeal/lumina-css/client/public/lumina-components.css">\n<script defer src="https://cdn.jsdelivr.net/gh/Godszeal/lumina-css/client/public/lumina-interactions.js"></script>\n<script defer src="https://cdn.jsdelivr.net/gh/Godszeal/lumina-css/client/public/lumina-icons.js"></script>'} /></div></>; }

function CommerceDocs() { return <><DocsHeader index="09" eyebrow="Commerce kit" title="Sell with structure." body="Commerce patterns for product discovery, carts, checkout, order status, and trust signals. Add the optional commerce stylesheet without changing Lumina’s stable core URL." /><div className="mt-10 flex flex-wrap gap-3"><span className="lu-badge"><LuminaIcon name="bag" size={13} /> storefront</span><span className="lu-badge"><LuminaIcon name="creditCard" size={13} /> checkout</span><span className="lu-badge"><LuminaIcon name="truck" size={13} /> fulfillment</span></div><div className="mt-8 lu-product-grid"><article className="lu-product-card"><div className="lu-product-media"><LuminaIcon name="bag" size={52} /></div><div className="lu-product-body"><span className="lu-product-kicker">New / everyday carry</span><h3 className="lu-product-title">Soft utility bag</h3><div className="mt-3 lu-rating"><LuminaIcon name="star" size={14} /> 4.9 <span className="lu-rating-count">128 reviews</span></div><div className="lu-product-price"><span className="lu-product-price-current">$84</span><span className="lu-product-price-old">$105</span></div><button className="lu-btn lu-btn-primary mt-4"><LuminaIcon name="cart" size={14} /> Add to cart</button></div><span className="lu-sale-ribbon">20% off</span></article><article className="lu-product-card"><div className="lu-product-media"><LuminaIcon name="package" size={52} /></div><div className="lu-product-body"><span className="lu-product-kicker">Desk / modular</span><h3 className="lu-product-title">Signal organizer</h3><div className="mt-3 lu-rating"><LuminaIcon name="star" size={14} /> 4.8 <span className="lu-rating-count">64 reviews</span></div><div className="lu-product-price"><span className="lu-product-price-current">$42</span></div><button className="lu-btn lu-btn-outline mt-4"><LuminaIcon name="heartPlus" size={14} /> Save item</button></div></article><article className="lu-product-card"><div className="lu-product-media"><LuminaIcon name="gift" size={52} /></div><div className="lu-product-body"><span className="lu-product-kicker">Limited / seasonal</span><h3 className="lu-product-title">Build kit gift set</h3><div className="mt-3 lu-rating"><LuminaIcon name="star" size={14} /> 5.0 <span className="lu-rating-count">32 reviews</span></div><div className="lu-product-price"><span className="lu-product-price-current">$120</span></div><button className="lu-btn lu-btn-primary mt-4"><LuminaIcon name="gift" size={14} /> Choose gift</button></div></article></div><div className="mt-10 grid gap-6 lg:grid-cols-2"><div className="lu-card lu-shadow"><SectionLabel index="09A" children="Cart + order states" /><div className="mt-5 lu-cart-line"><div className="lu-neu-icon lu-neu-icon-sm"><LuminaIcon name="package" size={18} /></div><div><strong className="block text-sm">Signal organizer</strong><span className="lu-help">Ships in 2–3 days</span></div><strong>$42</strong></div><div className="mt-6 lu-order-timeline"><div className="lu-order-step" data-lu-complete="true"><span className="lu-order-marker"><LuminaIcon name="check" size={14} /></span><span><strong className="block text-sm">Order confirmed</strong><span className="lu-help">Payment accepted</span></span></div><div className="lu-order-step"><span className="lu-order-marker"><LuminaIcon name="truck" size={14} /></span><span><strong className="block text-sm">Preparing shipment</strong><span className="lu-help">Warehouse processing</span></span></div></div></div><CodeBlock value={'<link rel="stylesheet" href="https://cdn.jsdelivr.net/gh/Godszeal/lumina-css/client/public/lumina-commerce.css">\n<div class="lu-product-grid">\n  <article class="lu-product-card">...</article>\n</div>'} /></div></>; }

function CheckoutDocs() { const [items, setItems] = useState([{ id: "bag", name: "Soft utility bag", price: 84, qty: 1 }, { id: "organizer", name: "Signal organizer", price: 42, qty: 2 }]); const [coupon, setCoupon] = useState(""); const [couponState, setCouponState] = useState<"idle" | "valid" | "invalid">("idle"); const [shipping, setShipping] = useState("standard"); const [email, setEmail] = useState(""); const [card, setCard] = useState(""); const [submitted, setSubmitted] = useState(false); const [error, setError] = useState(""); const subtotal = items.reduce((sum, item) => sum + item.price * item.qty, 0); const discount = couponState === "valid" ? subtotal * .1 : 0; const shippingCost = shipping === "express" ? 18 : subtotal >= 100 ? 0 : 8; const total = subtotal - discount + shippingCost; const updateQty = (id: string, delta: number) => setItems((current) => current.map((item) => item.id === id ? { ...item, qty: Math.max(0, item.qty + delta) } : item).filter((item) => item.qty > 0)); const applyCoupon = (value = coupon) => setCouponState(value.trim().toUpperCase() === "LUMINA10" ? "valid" : "invalid"); const submit = (event: React.FormEvent) => { event.preventDefault(); if (!email.includes("@") || card.replace(/\\s/g, "").length < 12) { setError("Add a valid email and a 12+ digit payment number to continue."); setSubmitted(false); return; } setError(""); setSubmitted(true); }; return <><DocsHeader index="10" eyebrow="Checkout flow" title="From cart to confirmation." body="A complete checkout interaction layer for storefronts. State stays readable, controls are touch-friendly, and every transition has a success or recovery path." /><div className="mt-10 flex flex-wrap gap-3"><span className="lu-stepper" data-lu-step="active"><span className="lu-stepper-dot">1</span> Cart</span><span className="lu-stepper" data-lu-step={items.length ? "active" : "idle"}><span className="lu-stepper-dot">2</span> Delivery</span><span className="lu-stepper" data-lu-step={submitted ? "active" : "idle"}><span className="lu-stepper-dot">3</span> Confirmation</span></div><div className="mt-8 lu-checkout lu-checkout-shell" data-lu-checkout data-lu-checkout-state={submitted ? "success" : error ? "error" : "idle"}><form className="lu-checkout-form space-y-6" onSubmit={submit}><div className="lu-card"><div className="flex items-center justify-between"><div><SectionLabel index="10A" children="Your cart" /><h3 className="mt-3 font-display text-2xl font-bold">Review items</h3></div><span className="lu-cart-badge">{items.reduce((sum, item) => sum + item.qty, 0)}</span></div><div className="mt-5">{items.map((item) => <div className="lu-cart-line" key={item.id}><div className="lu-neu-icon lu-neu-icon-sm"><LuminaIcon name={item.id === "bag" ? "bag" : "package"} size={17} /></div><div><strong className="block text-sm">{item.name}</strong><span className="lu-help">${item.price.toFixed(2)} each</span></div><div className="lu-quantity"><button type="button" aria-label={`Decrease ${item.name}`} onClick={() => updateQty(item.id, -1)}>−</button><output aria-label={`${item.name} quantity`}>{item.qty}</output><button type="button" aria-label={`Increase ${item.name}`} onClick={() => updateQty(item.id, 1)}>+</button></div></div>)}</div></div><div className="lu-card"><SectionLabel index="10B" children="Delivery" /><div className="mt-5 lu-choice-list"><label className="lu-choice"><input type="radio" name="shipping" value="standard" checked={shipping === "standard"} onChange={() => setShipping("standard")} /><span className="lu-choice-copy"><span className="lu-choice-title">Standard delivery · {subtotal >= 100 ? "Free" : "$8"}</span><span className="lu-choice-meta">Arrives in 4–6 business days</span></span></label><label className="lu-choice"><input type="radio" name="shipping" value="express" checked={shipping === "express"} onChange={() => setShipping("express")} /><span className="lu-choice-copy"><span className="lu-choice-title">Express delivery · $18</span><span className="lu-choice-meta">Arrives in 1–2 business days</span></span></label></div></div><div className="lu-card"><SectionLabel index="10C" children="Payment" /><div className="mt-5 grid gap-3"><label className="grid gap-2 text-sm font-semibold">Email<input className="lu-input" type="email" value={email} onChange={(event) => setEmail(event.target.value)} placeholder="you@example.com" data-lu-checkout-email /></label><label className="grid gap-2 text-sm font-semibold">Card number<input className="lu-input" inputMode="numeric" value={card} onChange={(event) => setCard(event.target.value)} placeholder="4242 4242 4242 4242" data-lu-checkout-card /></label></div></div><button className="lu-btn lu-btn-primary w-full" type="submit"><LuminaIcon name="lock" size={15} /> Pay ${total.toFixed(2)}</button>{error && <p className="lu-checkout-message lu-checkout-error block" role="alert">{error}</p>}</form><aside className="lu-checkout-summary"><SectionLabel index="10D" children="Summary" /><div className="mt-5"><div className="lu-price-row"><span>Subtotal</span><strong>${subtotal.toFixed(2)}</strong></div><div className="lu-price-row"><span>Shipping</span><strong>{shippingCost ? `$${shippingCost.toFixed(2)}` : "Free"}</strong></div>{couponState === "valid" && <div className="lu-price-row"><span>Coupon</span><strong>−${discount.toFixed(2)}</strong></div>}<div className="lu-price-row lu-price-row-total"><span>Total</span><strong>${total.toFixed(2)}</strong></div></div><form className="mt-6" onSubmit={(event) => { event.preventDefault(); const field = event.currentTarget.querySelector("input"); applyCoupon(field?.value || ""); }}><label className="grid gap-2 text-xs font-semibold">Coupon code<div className="lu-coupon-row"><input className="lu-input" value={coupon} onChange={(event) => setCoupon(event.target.value)} placeholder="LUMINA10" /><button className="lu-btn lu-btn-outline" type="submit">Apply</button></div></label><p className="lu-coupon-message" data-lu-coupon-state={couponState}>{couponState === "valid" ? "Coupon applied — 10% off." : couponState === "invalid" ? "Coupon not recognized." : "Try LUMINA10 for the demo."}</p></form><div className="lu-checkout-confirmation mt-6" data-lu-confirmation={submitted ? "true" : "false"}><LuminaIcon name="success" className="text-[var(--lu-commerce-accent)]" /><strong className="mt-3 block">Order confirmed</strong><p className="mt-2 text-sm text-muted-foreground">Your receipt is ready. This preview keeps the transaction local and does not submit payment.</p></div></aside></div><div className="mt-8"><CodeBlock value={'<link rel="stylesheet" href="https://cdn.jsdelivr.net/gh/Godszeal/lumina-css/client/public/lumina-commerce.css">\n<script defer src="https://cdn.jsdelivr.net/gh/Godszeal/lumina-css/client/public/lumina.js"></script>\n<div class="lu-checkout" data-lu-checkout>...</div>'} /></div></>; }

function Theming() { return <><DocsHeader index="06" eyebrow="Theming" title="Make it yours." body="Lumina uses CSS custom properties so you can shift the system without rewriting its grammar. Keep the cobalt slash, or replace it with your own signal." /><div className="mt-12 grid gap-6 lg:grid-cols-2"><CodeBlock value={':root {\n  --lu-cobalt: #315CFF;\n  --lu-paper: #F7F7F3;\n  --lu-ink: #111827;\n  --lu-radius: .55rem;\n}'} /><div className="border border-border bg-card p-6"><SectionLabel index="06A" children="Dark mode" /><p className="mt-5 text-sm leading-7 text-muted-foreground">Set <code className="text-[#315CFF]">data-lu-theme="dark"</code> on the root element. The CDN script remembers the user’s choice when you use the theme toggle helper.</p><div className="mt-6 rounded-sm bg-foreground p-5 text-background"><code className="font-mono text-xs">&lt;html data-lu-theme="dark"&gt;</code></div></div></div></>; }
function MotionDocs() { return <><DocsHeader index="07" eyebrow="Motion" title="Move with intent." body="Motion is short, interruptible, and reserved for feedback. Lumina avoids ornamental loops and respects reduced-motion preferences." /><div className="mt-12 grid gap-3 md:grid-cols-3"><DocCard title="Press" icon="arrow">Buttons compress to 97% on active. It makes the interface feel listened to.</DocCard><DocCard title="Lift" icon="spark">Cards lift by a few pixels on hover, with a crisp shadow instead of a floating cloud.</DocCard><DocCard title="Reveal" icon="motion">Content enters with opacity and translate only, keeping layout stable and GPU-friendly.</DocCard></div><div className="mt-8"><CodeBlock value={'@media (prefers-reduced-motion: reduce) {\n  *, *::before, *::after {\n    animation-duration: .01ms !important;\n    transition-duration: .01ms !important;\n  }\n}'} /></div></>; }
function AccessibilityDocs() { return <><DocsHeader index="08" eyebrow="Accessibility" title="Make the signal clear." body="A visual system is only useful when people can read, focus, navigate, and understand it. Lumina’s defaults are designed to leave room for semantic HTML and accessible intent." /><div className="mt-12 grid gap-3 md:grid-cols-2"><DocCard title="Focus is visible" icon="accessibility">Do not remove the focus ring. Pair interactive controls with a strong visible focus state.</DocCard><DocCard title="Color is not the only cue" icon="palette">Use text, iconography, and status labels alongside color so meaning survives different visual contexts.</DocCard><DocCard title="Icons have a role" icon="spark">Decorative icons are hidden from assistive technology. Meaningful icons receive a label or adjacent text.</DocCard><DocCard title="Mobile is first" icon="grid">Keep touch targets generous and let dense multi-column layouts collapse into a readable sequence.</DocCard></div><div className="mt-8 border border-[#315CFF]/30 bg-[#315CFF]/8 p-6"><div className="flex items-start gap-3"><LuminaIcon name="check" className="mt-1 text-[#315CFF]" /><p className="text-sm leading-7">Use the visual system to support content hierarchy, not to replace semantic structure. Lumina styles the interface; your markup carries the meaning.</p></div></div></>; }
